ass="pager"><button name="Page" value="@(page-1)" disabled="@(outcome!="found"||page<=1)">前へ</button><span>@(page) / @Math.Max(1,(count+Model.PageSize-1)/Model.PageSize)</span><button name="Page" value="@(page+1)" disabled="@(outcome!="found"||page*Model.PageSize>=count)">次へ</button></nav></form>

